import { redirect } from "next/navigation";

import { auth, signOut } from "@/auth";
import { getUser, listUsers } from "@/lib/users";

export default async function DashboardPage() {
  const session = await auth();
  // Belt and suspenders: proxy.ts already redirects unauthenticated requests
  // away from /dashboard, but the page stands on its own if reached directly.
  if (!session?.user) {
    redirect("/sign-in?callbackUrl=/dashboard");
  }

  const me = await getUser(session.user.id);
  const all = await listUsers();

  return (
    <main className="mx-auto max-w-2xl p-8">
      <div className="flex items-start justify-between">
        <h1 className="text-2xl font-semibold">Dashboard</h1>
        <form
          action={async () => {
            "use server";
            await signOut({ redirectTo: "/" });
          }}
        >
          <button type="submit" className="text-sm underline opacity-70 hover:opacity-100">
            Sign out
          </button>
        </form>
      </div>
      <p className="mt-2 text-sm opacity-70">
        Signed in as {me?.name ?? session.user.name ?? "nobody"} (
        {me?.email ?? session.user.email ?? "—"})
      </p>

      <h2 className="mt-8 text-lg font-medium">Team</h2>
      <ul className="mt-2 space-y-1">
        {all.map((u) => (
          <li key={u.id} className="text-sm">
            {u.name} — {u.email} — joined {u.createdAt}
          </li>
        ))}
      </ul>
    </main>
  );
}

